import { useEffect, useState } from 'react';
import type { ArchiveIndex, BioRecord, DailyDataset, RunStatus, SourcesFile } from '../../shared/schema';

/** Data mode: "live" reads ./data (generated by the pipeline); "demo" reads the dev-only demo fixtures. */
export const DATA_MODE: 'live' | 'demo' = import.meta.env.VITE_DATA_MODE === 'demo' ? 'demo' : 'live';
const DATA_ROOT = DATA_MODE === 'demo' ? '/demo-data/' : `${import.meta.env.BASE_URL}data/`;

export class NotFoundError extends Error {}

const cache = new Map<string, Promise<unknown>>();

export function loadJson<T>(file: string): Promise<T> {
  const url = `${DATA_ROOT}${file}`;
  if (!cache.has(url)) {
    const p = fetch(url, { cache: 'no-cache' }).then(async (res) => {
      if (res.status === 404) throw new NotFoundError(`${file} not found`);
      if (!res.ok) throw new Error(`Failed to load ${file} (HTTP ${res.status})`);
      return (await res.json()) as T;
    });
    p.catch(() => cache.delete(url));
    cache.set(url, p);
  }
  return cache.get(url) as Promise<T>;
}

export interface AsyncState<T> {
  data: T | null;
  error: Error | null;
  loading: boolean;
}

export function useAsync<T>(fn: () => Promise<T>, deps: unknown[]): AsyncState<T> {
  const [state, setState] = useState<AsyncState<T>>({ data: null, error: null, loading: true });
  useEffect(() => {
    let alive = true;
    setState((s) => ({ ...s, loading: true, error: null }));
    fn().then(
      (data) => alive && setState({ data, error: null, loading: false }),
      (error: Error) => alive && setState({ data: null, error, loading: false }),
    );
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
  return state;
}

export const useLatest = () => useAsync(() => loadJson<DailyDataset>('latest.json'), []);
export const useStatus = () => useAsync(() => loadJson<RunStatus>('status.json').catch(() => null), []);
export const useSources = () => useAsync(() => loadJson<SourcesFile>('sources.json'), []);
export const useArchiveIndex = () => useAsync(() => loadJson<ArchiveIndex>('archive/index.json'), []);
export const useArchiveDay = (date: string | undefined) =>
  useAsync(() => (date ? loadJson<DailyDataset>(`archive/${date}.json`) : Promise.reject(new NotFoundError('no date'))), [date]);

export type RangeKey = 'latest' | '7' | '30' | 'all';

/** Records for a range of archived days, merged and de-duplicated by record id (newest day wins). */
export async function loadRange(range: RangeKey): Promise<{ records: (BioRecord & { day: string })[]; days: string[] }> {
  if (range === 'latest') {
    const latest = await loadJson<DailyDataset>('latest.json');
    return { records: latest.records.map((r) => ({ ...r, day: latest.date })), days: [latest.date] };
  }
  const index = await loadJson<ArchiveIndex>('archive/index.json');
  const days = (range === 'all' ? index.days : index.days.slice(0, Number(range))).map((d) => d.date);
  const datasets = await Promise.all(days.map((d) => loadJson<DailyDataset>(`archive/${d}.json`).catch(() => null)));
  const byId = new Map<string, BioRecord & { day: string }>();
  datasets.forEach((ds) => {
    for (const r of ds?.records ?? []) if (!byId.has(r.id)) byId.set(r.id, { ...r, day: ds!.date });
  });
  return { records: [...byId.values()], days };
}
